import React, { useState, useEffect } from "react";
import ProductList from "./ProductList";
import Cart from "./Cart";
import { Product, Cart as CartType } from "./types";
import "./App.css";

function App() {
  const [products, setProducts] = useState<Product[]>([]);
  const [cart, setCart] = useState<CartType>({ items: [], total: 0 });
  const [showCart, setShowCart] = useState(false);

  useEffect(() => {
    fetch("/api/products")
      .then((res) => res.json())
      .then(setProducts);
  }, []);

  const fetchCart = () => {
    fetch("/api/cart")
      .then((res) => res.json())
      .then(setCart);
  };

  useEffect(() => {
    fetchCart();
  }, []);

  const addToCart = (productId: number) => {
    fetch(`/api/cart/${productId}`, { method: "POST" })
      .then((res) => res.json())
      .then(() => fetchCart());
  };

  const removeFromCart = (productId: number) => {
    fetch(`/api/cart/${productId}`, { method: "DELETE" })
      .then((res) => res.json())
      .then(() => fetchCart());
  };

  return (
    <div className="app">
      <header className="header">
        <h1>Purrfect Prints</h1>
        <p className="subtitle">Fine art photography, by cats, of cats, for cats.</p>
        <button className="cart-toggle" onClick={() => setShowCart(!showCart)}>
          Cart ({cart.items.reduce((sum, item) => sum + item.quantity, 0)})
        </button>
      </header>

      {showCart ? (
        <Cart cart={cart} onRemove={removeFromCart} onBack={() => setShowCart(false)} />
      ) : (
        <ProductList products={products} onAdd={addToCart} />
      )}
    </div>
  );
}

export default App;
